"""Business logic kept out of the DAG file, so it can be tested without a scheduler."""


def summarise(rows):
    """Turn (category, amount, status) rows into {category: (orders, paid)}, paid rounded to cents."""
    summary = {}
    for category, amount, status in rows:
        orders, paid = summary.get(category, (0, 0.0))
        summary[category] = (orders + 1, paid + (amount if status == "paid" else 0.0))
    return {category: (orders, round(paid, 2)) for category, (orders, paid) in sorted(summary.items())}

