"""Unit tests for the business logic: plain Python, no Airflow needed."""

from shop_lib.revenue import summarise


def test_only_paid_orders_count_as_revenue():
    rows = [("home", 10.0, "paid"), ("home", 5.0, "refunded"), ("beauty", 2.5, "paid")]
    assert summarise(rows) == {"beauty": (1, 2.5), "home": (2, 10.0)}


def test_no_orders_gives_an_empty_summary():
    assert summarise([]) == {}
